QUnit.test('Test SuperHuman class is defined', function(assert) {
   assert.ok(typeof SuperHuman === 'function', 'SuperHuman class exists');
});

QUnit.test('Test SuperHuman class constructor with new SuperHuman(\'Human Name\', 6)', function(assert) {
   assert.ok(typeof SuperHuman === 'function', 'SuperHuman class exists');
   assert.equal(SuperHuman.prototype.constructor.length, 2, 'Constructor has 2 parameters');

   const hero = new SuperHuman('Human Name', 6);
   assert.equal(hero.name, 'Human Name', 'name property set by constructor');
   assert.equal(hero.powerLevel, 6, 'powerLevel property set by constructor');
});

QUnit.test('Test SuperHero class is defined', function(assert) {
   assert.ok(typeof SuperHero === 'function', 'SuperHero class exists');
   assert.ok(SuperHero.prototype instanceof SuperHuman, 'SuperHero extends SuperHuman class');
});

QUnit.test('Test SuperHero class constructor with new SuperHero(\'Hero Name\', \'Hero Alias\', 5)', function(assert) {
   assert.ok(typeof SuperHero === 'function', 'SuperHero class exists');
   assert.equal(SuperHero.prototype.constructor.length, 3, 'Constructor has 3 parameters');

   const hero = new SuperHero('Hero Name', 'Hero Alias', 5);
   assert.equal(hero.name, 'Hero Name', 'Hero name set by constructor');
   assert.equal(hero.alias, 'Hero Alias', 'Hero alias set by constructor');
   assert.equal(hero.powerLevel, 5, 'Hero powerLevel set by constructor');
});

QUnit.test('Test SuperHero battle() method', function(assert) {
   assert.ok(typeof SuperHero === 'function', 'SuperHero class exists');
   assert.ok(typeof SuperHero.prototype.battle === 'function', 'battle() method exists');
   assert.ok(typeof SuperVillain === 'function', 'SuperVillain class exists');

   const hero = new SuperHero('Hero Name', 'Hero Alias', 5);
   const villain = new SuperVillain('Villain Name', 'Villain Alias', 5);

   assert.equal(hero.battle(villain), true, 'Hero with power 5 defeats villain with power level 5');

   villain.powerLevel = 6;

   assert.equal(hero.battle(villain), false, 'Hero with power 5 loses to villain with power level 6');
});

QUnit.test('Test SuperVillain is defined', function(assert) {
   assert.ok(typeof SuperVillain === 'function', 'SuperVillain class exists');
   assert.ok(SuperVillain.prototype instanceof SuperHuman, 'SuperVillain extends SuperHuman class');
});

QUnit.test('Test SuperVillain class constructor with new SuperVillain(\'Villain Name\', \'Villain Alias\', 3)', function(assert) {
   assert.ok(typeof SuperVillain === 'function', 'SuperVillain class exists');
   assert.equal(SuperVillain.prototype.constructor.length, 3, 'Constructor has 3 parameters');

   const villain = new SuperVillain('Villain Name', 'Villain Alias', 3);
   assert.equal(villain.name, 'Villain Name', 'Villain name set by constructor');
   assert.equal(villain.alias, 'Villain Alias', 'Villain alias set by constructor');
   assert.equal(villain.powerLevel, 3, 'Villain powerLevel set by constructor');
});

QUnit.test('Test SuperVillain getEvilChuckle() method', function(assert) {
   assert.ok(typeof SuperVillain === 'function', 'SuperVillain class exists');
   assert.ok(typeof SuperVillain.prototype.getEvilChuckle === 'function', 'getEvilChuckle() method exists');

   const villain = new SuperVillain('Villain Name', 'Villain Alias', 3);

   assert.equal(villain.getEvilChuckle(), 'Ha ha ha!', 'getEvilChuckle() returns correct string');
});
